		"0 15 10 * * ? some text", // contains valid cron at the beginning  
		"prefix 0 15 10 * * ? suffix", // contains valid cron in middle
		"just wrong 0 15 10 * * ?", // contains valid cron with extra "wrong" prefix
	}

	fmt.Println("Testing cron validator with strings containing cron-like substrings:")
	for _, test := range testCases {
		errs := validate.Var(test, "cron")
		if errs == nil {
			fmt.Printf("❌ '%s' - SHOULD FAIL but passed validation\n", test)
		} else {
			fmt.Printf("✅ '%s' - correctly failed validation\n", test)
		}
	}

	// Test cases that should PASS and do pass
	validCases := []string{
		"0 15 10 * * ?",
		"0 15 10 ? * *",
		"0 */15 * * *",
	}

	fmt.Println("\nTesting cron validator with valid cron expressions:")
	for _, test := range validCases {
		errs := validate.Var(test, "cron")
		if errs == nil {
			fmt.Printf("✅ '%s' - correctly passed validation\n", test)
		} else {
			fmt.Printf("❌ '%s' - SHOULD PASS but failed validation\n", test)
		}
	}
}

