package main

import (
	"regexp"
)

func main() {
	// This is the original cron regex from the codebase
	cronRegexString := `(@(annually|yearly|monthly|weekly|daily|hourly|reboot))|(@every (\d+(ns|us|µs|ms|s|m|h))+)|((((\d+,)+\d+|((\*|\d+)(\/|-)\d+)|\d+|\*) ?){5,7})`

	// This is what we should use after our fix
	fixedCronRegexString := `^(@(annually|yearly|monthly|weekly|daily|hourly|reboot))|(@every (\d+(ns|us|µs|ms|s|m|h))+)|((((\d+,)+\d+|((\*|\d+)(\/|-)\d+)|\d+|\*) ?){5,7})$`

	cronRegex := regexp.MustCompile(cronRegexString)
	fixedCronRegex := regexp.MustCompile(fixedCronRegexString)

	// Test cases that should be false but are currently true due to non-anchored regex
	testCases := []string{
		"some text 0 15 10 * * ?", // contains valid cron at the end
		"0 15 10 * * ? some text", // contains valid cron at the beginning  
		"prefix 0 15 10 * * ? suffix", // contains valid cron in middle
		"wrong 0 15 10 * * ?", // contains valid cron with extra prefix
		"0 15 10 * * ?",         // should be true (valid cron)
		"just wrong",
	}

	println("Original (non-anchored) regex behavior:")
	for _, test := range testCases {
		match := cronRegex.MatchString(test)
		println(test + " -> " + string(rune(match + '0'))) 
	}

	println("\nFixed (anchored) regex behavior:")
	for _, test := range testCases {
		match := fixedCronRegex.MatchString(test)
		println(test + " -> " + string(rune(match + '0')))
	}
}

